import React, { useState } from 'react';
import axios from 'axios';

const ExerciseCard = ({ exercise, currentAccount }) => {
  const [selected, setSelected] = useState(null);
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    if (selected === null) return alert("Chọn đáp án đi bạn!");
    if (!currentAccount) return alert("Kết nối ví trước!");

    setLoading(true);
    try {
      const res = await axios.post('http://localhost:5000/api/submit-answer', {
        exercise_id: exercise._id,
        learner_address: currentAccount,
        selected_option_index: selected
      });
      setResult(res.data);
    } catch (err) {
      alert("Lỗi: " + err.response?.data?.error || err.message);
    }
    setLoading(false);
  };

  return (
    <div className={`p-4 border rounded-lg shadow-sm mb-4 transition-all ${result?.is_correct === true ? 'bg-green-50 border-green-300' : result?.is_correct === false ? 'bg-red-50 border-red-300' : 'bg-white'}`}>
      {/* Header */}
      <div className="flex justify-between items-center mb-2">
        <span className="bg-blue-100 text-blue-800 text-xs font-semibold px-2.5 py-0.5 rounded">
          {exercise.topic}
        </span>
        <span className="text-xs text-gray-500 font-mono">
          Creator: {exercise.creator_address.slice(0, 6)}...{exercise.creator_address.slice(-4)}
        </span>
      </div>

      {/* Question */}
      <h3 className="font-bold text-gray-800 mb-3">{exercise.question_content}</h3>

      {/* Options */}
      <div className="space-y-2">
        {exercise.options.map((opt, idx) => (
          <button
            key={idx}
            disabled={!!result}
            onClick={() => setSelected(idx)}
            className={`w-full text-left p-2 rounded border ${
              selected === idx ? 'bg-indigo-100 border-indigo-500 ring-1 ring-indigo-500' : 'border-gray-200 hover:bg-gray-50'
            }`}
          >
            {["A", "B", "C", "D"][idx]}. {opt}
          </button>
        ))}
      </div>

      {/* Action Footer */}
      <div className="mt-4 flex justify-between items-center">
        <div className="text-sm">
          <span className="text-red-500 font-bold mr-2">Cược: {exercise.stake_amount}</span>
          <span className="text-green-600 font-bold">Thưởng: 10</span>
        </div>
        
        {!result ? (
          <button 
            onClick={handleSubmit} 
            disabled={loading}
            className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded text-sm font-medium disabled:opacity-50"
          >
            {loading ? "Đang xử lý..." : "Chốt đáp án"}
          </button>
        ) : (
          <div className={`font-bold ${result.is_correct ? 'text-green-600' : 'text-red-600'}`}>
            {result.message}
          </div>
        )}
      </div>
    </div>
  );
};

export default ExerciseCard;
